const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ args: ['--autoplay-policy=no-user-gesture-required'] });
  const page = await browser.newPage({ locale: 'ar-EG', viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  await page.addInitScript(() => {
    const d = Object.getOwnPropertyDescriptor(HTMLMediaElement.prototype, 'src');
    Object.defineProperty(HTMLMediaElement.prototype, 'src', { set(v) { console.log('SRC SET', v); d.set.call(this, v); }, get() { return d.get.call(this); } });
    const play = HTMLMediaElement.prototype.play;
    HTMLMediaElement.prototype.play = function () { console.log('PLAY', this.currentSrc || this.src); return play.call(this); };
    for (const ev of ['ended', 'error', 'playing']) document.addEventListener(ev, e => console.log('EV', ev, e.target.currentSrc), true);
  });
  page.on('console', m => { const t = m.text(); if (/SRC|PLAY|EV|play failed/.test(t)) console.log(t); });
  page.on('pageerror', e => console.log('pageerror', e.message));
  const shot = async n => page.screenshot({ path: `shots/${n}.png` });
  await page.goto('https://ottian.github.io/azkarelmuslim/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(5000); await shot('1-live');
  console.log('--- tap reciters tab');
  await page.mouse.click(244, 800); await page.waitForTimeout(2000);
  await page.mouse.click(195, 84); await page.keyboard.type('هزاع'); await page.waitForTimeout(1500); await shot('2-search');
  await page.mouse.click(195, 190); await page.waitForTimeout(2000); await shot('3-reciter');
  console.log('--- tap 7th surah (الحجر)');
  await page.mouse.click(195, 518); await page.waitForTimeout(8000); await shot('4-playing');
  console.log('--- back, live tab, tap first radio, then reciters again and Hijr');
  await page.mouse.click(362, 28); await page.waitForTimeout(1000);
  await page.mouse.click(341, 800); await page.waitForTimeout(1500);
  await page.mouse.click(195, 140); await page.waitForTimeout(6000); await shot('5-radio');
  await page.mouse.click(244, 800); await page.waitForTimeout(1500);
  await page.mouse.click(195, 190); await page.waitForTimeout(2000);
  await page.mouse.click(195, 518); await page.waitForTimeout(8000); await shot('6-after-radio');
  await browser.close();
})();
